    body: "日本の学校給食は1889年、山形県鶴岡町の私立忠愛小学校で貧困家庭の欠食児童に昼食を提供したのが始まりとされます。その後大正期には都市部の一部学校でも実施が広がりましたが、全国的な制度としては未整備のままでした。\n\n戦後まもない食糧難のなか、児童の栄養状態改善は緊急課題となり、1946年にはアメリカの民間団体ララ(アジア救援公認団体)からの物資援助を受けて学校給食が再開されました。1954年には学校給食法が制定され、教育の一環として学校給食を実施することが法的に位置づけられました。\n\n給食はパンと脱脂粉乳中心から、米飯給食の導入など時代とともに内容を変化させながら、児童の健康保持とともに食育の重要な場としての役割を担うようになりました。今日では地産地消や食物アレルギー対応など、学校給食は食育・健康教育政策の中心的な柱の一つとなっています。",
