    body: "専修学校制度は1975年(昭和50年)7月の学校教育法改正により創設され、1976年1月に施行されました。それまで各種学校として法的位置づけが曖昧だった職業教育機関のうち、修業年限1年以上、年間授業時数800時間以上、常時40人以上の生徒在籍などの設置基準を満たすものを、新たな学校種として位置づけたものです。\n\n専修学校は入学資格に応じて、中学校卒業者を対象とする高等課程、高等学校卒業者を対象とする専門課程(いわゆる専門学校)、資格を問わない一般課程の3課程に分けられ、看護・情報・デザイン・調理など多様な職業分野の実践的教育を担っています。\n\n専修学校制度の創設は、大学進学一辺倒ではない多様な進路選択を制度的に保障した点で意義があり、今日では専門学校卒業者に対する専門士・高度専門士の称号付与や、大学への編入学制度など、他の学校種との接続も整備されています。",
