    body: "戦前の日本の学校体系は、小学校卒業後に中学校・高等女学校・実業学校・師範学校などへ分岐する複線型で、進路によって上級学校への接続経路が大きく異なっていました。米国教育使節団はこの複線型を批判し、誰もが同じ経路をたどれる単線型の学校体系への転換を提言しました。\n\n教育刷新委員会はこの提言を受けて具体的な制度設計を進め、小学校6年・新制中学校3年を義務教育とし、その上に高等学校3年、大学4年を置く六・三・三・四制を採用することを決定しました。実施にあたっては、財政難のなか新制中学校の校舎確保や教員配置を短期間で行う必要があり、間借り授業や青空教室など現場は大きな混乱に見舞われました。\n\nこうした困難を乗り越えて1947年度に新制中学校が、1948年度に新制高等学校が発足し、単線型の学校体系が定着しました。六・三・三・四制の成立過程は、理念先行の制度改革を現場が支えて実現させた戦後教育史の重要な一幕です。",
