    body: "教育二法とは、1954年に制定された「義務教育諸学校における教育の政治的中立の確保に関する臨時措置法」と、教育公務員特例法の一部改正法を指す通称です。占領終結後、日本教職員組合による政治的な教育運動が活発化するなかで、当時の政府・与党が教育の政治的中立性の確保を掲げて法制化を進めました。\n\nこの法律により、義務教育諸学校の教員が児童生徒に対して特定の政党を支持・反対させる教育を行うことや、教職員組合が教員に対しそうした教育を行わせる目的で活動することが禁止されました。日教組をはじめとする教育関係者からは、教育への政治的介入であり教育の自由を侵すものだとして強い反対運動が展開されました。\n\n教育二法をめぐる論争は、教育の政治的中立性をどのように確保するかという問題を鮮明にし、後の教育基本法における政治的中立性規定の解釈や、教員の政治的行為の制限をめぐる議論の重要な起点となりました。",
