    body: "郷学(郷校とも表記)は、藩士のための藩校と庶民のための寺子屋の中間に位置づけられる教育施設で、江戸時代から明治初年にかけて各地に設立された。対象は下級武士、郷士、町民、農民など幅広い階層の子弟に及び、内容も読み書き・算盤の初歩から四書五経などの漢籍、和算(日本独自の数学)まで多岐にわたった。\n\n設立の形態は一様ではなく、藩が本藩の藩校の分校として設けたもの、藩と地元の町方・農民が共同で設立したもの、庶民が自主的な組合組織として設けたものなど多様であった。研究上は、藩校の分校的存在、藩が庶民教育のために設けた機関、庶民の共同出資による地方学校の三類型に大別されることが多い。設立が本格化するのは19世紀に入ってからで、代表例として岡山藩が寛文10年(1670年)に開いた閑谷学校が最古級の郷学として知られる。\n\n郷学は明治初年にも各地で新設が続いたが、明治5年(1872年)の学制公布以降は近代的な小学校制度へと再編・吸収されていった。江戸期の多様な教育インフラが明治の学校体系に接続していく過程を示す事例として、教育史上重要な位置を占めている。",
