    body: "昌平坂学問所(昌平黌)は、江戸幕府直轄の教育機関である。起源は寛永7年(1630年)、三代将軍徳川家光が儒学者林羅山に上野忍岡の土地を与えて開かせた家塾に遡り、元禄3年(1690年)には五代将軍徳川綱吉の命で神田湯島に移転・拡張され、孔子を祀る大成殿を中心とする学問所として整備された。\n\n幕府直轄の官立学校としての性格が明確になったのは寛政期である。老中松平定信は寛政2年(1790年)に寛政異学の禁を発し、朱子学を正学として湯島の学問所で講じるよう命じた。寛政9年(1797年)には林家の私塾としての性格を切り離し、幕府が直接運営する正規の学問所として確立、名称も昌平坂学問所と称するようになった。以後、旗本・御家人の子弟や諸藩から派遣された藩士らが学び、幕末の人材育成に大きな役割を果たした。\n\n明治維新後、昌平坂学問所は新政府に接収され、大学校・大学本校などに改組された後、明治4年(1871年)に廃止された。その学統は東京大学の源流の一つともされ、江戸期の武士教育が近代高等教育へと接続する結節点として位置づけられている。",
