    body: "尋常小学校は、明治19年(1886年)4月10日に文部大臣森有礼のもとで公布された小学校令により制度化された初等教育機関である。この令により小学校は尋常小学校と高等小学校の二段階に再編され、修業年限は各4年、就学の学齢は満6歳から14歳までの8か年とされた。特に尋常小学校の4年間は、父母・後見人が児童を就学させる義務を負う正式な義務教育期間として位置づけられた点が画期的であった。\n\n一学級の生徒数は80人以下と定められ、その後明治33年(1900年)の小学校令改正では授業料が原則廃止され就学率が大きく向上するなど、尋常小学校は国民皆学の実現に向けた制度的基盤として機能し続けた。義務教育年限は明治40年(1907年)の改正でさらに6年に延長され、尋常小学校の修業年限もこれに合わせて6年制となった。\n\n尋常小学校の名称と制度は昭和16年(1941年)の国民学校令公布により国民学校初等科に改編されるまで用いられ、戦後は学校教育法(1947年)により現在の小学校制度へと引き継がれた。近代日本における国民統合と識字率向上を支えた基礎的な制度として、教育史上重要な位置を占める。",
