    categories: ["history"],
    summary:
      "明治5年(1872年)の学制公布に伴い導入された、全国を大学区・中学区・小学区に区分してそれぞれに大学・中学校・小学校を配置する構想。フランスの制度を範としたが実情に合わず短期間で改編された。",
    body: "学区制は、明治5年(1872年)に太政官布告として公布された学制の中核をなす制度構想である。学制はフランスの中央集権的な教育行政制度を範として、全国を8つの大学区に分け、各大学区をさらに32の中学区に、各中学区をさらに210の小学区に細分するという、合計で数万に及ぶ小学校の設置を想定した壮大な学区区分を定めた。それぞれの学区に大学・中学校・小学校を段階的に配置し、身分や性別を問わない国民皆学の実現を目指す点に大きな理念的意義があった。\n\nしかし、この構想はフランスの制度をそのまま模した机上のものであり、日本の地理的・財政的実情とは大きく乖離していた。公布の翌年である明治6年(1873年)には早くも大学区の数が8から7へと改められるなど、制度は当初から不安定であり、地方の実情を無視した画一的な学区割りは各地で住民の反発や就学率の伸び悩みを招いた。\n\n結果として学制自体が明治12年(1879年)、より地方の実情に即した教育令の公布によって廃止され、学区制も姿を消した。以後の日本の学校制度は市町村を基礎単位とする方式へと転換していくが、学区制の失敗は中央集権的な制度移植の限界を示す事例として、日本近代教育史上しばしば言及される。",
