    summary:
      "天皇・皇后の公式写真で、明治期以降学校に下賜され、教育勅語とともに最大級の敬意をもって保管された。火災時の救出をめぐり校長らが殉職・自死する事件も相次いだ。",
    body: "御真影とは、天皇・皇后の公式肖像写真の敬称である。明治期以降、文部省を通じて全国の学校に下賜されるようになり、明治24年(1891年)には文部省が御真影と教育勅語謄本を学校内の一定の場所に「最も鄭重に」奉安するよう訓令を発した。これを機に、御真影を専用に保管する奉安庫や奉安殿の設置が各地の学校で進むこととなった。\n\n御真影は単なる肖像写真ではなく、天皇制国家における学校儀式(始業式・終業式・三大節など)の中心的儀礼対象として扱われ、教職員・児童生徒には最大級の敬意ある取り扱いが求められた。そのため、火災や地震などの災害時に御真影を守ることは学校関係者、とりわけ校長にとって極めて重い責務とされ、明治31年(1898年)には長野県の学校で火災により御真影が焼失し校長が自死する事件が起きるなど、御真影の救出をめぐって校長らが殉職・自死する痛ましい事例が全国で相次いだ。大正期以降、こうした事例は美談として喧伝されることもあった。\n\n第二次世界大戦後、GHQの占領下で軍国主義・国家神道と結びついた教育制度の解体が進められ、御真影の奉安制度も教育勅語の失効とあわせて廃止された。御真影と奉安殿は、天皇を中心とする国家体制が学校教育の隅々にまで浸透していた戦前日本の姿を象徴する存在として、今日の教育史研究で取り上げられている。",
