    categories: ["history"],
    summary:
      "戦前・戦中期の学校に設けられた、御真影と教育勅語謄本を保管するための独立した堂宇。神社建築を模した造りが多く、防火・防災上の理由から校舎とは別棟で建設された。",
    body: "奉安殿は、御真影(天皇・皇后の写真)と教育勅語謄本を安置するために学校敷地内に設けられた独立の施設である。明治24年(1891年)の文部省訓令を契機に、まず校舎内の一室や金庫(奉安庫)に安置する形が広がったが、火災による焼失を防ぐため、次第に鉄筋コンクリート造や石造の耐火性の高い専用建築として校舎とは別棟に建設されるようになった。多くは神社の社殿を模した外観を持ち、児童生徒は登下校の際に最敬礼をすることが求められた。\n\n奉安殿の設置は昭和初期から戦時期にかけて全国的に広がり、国家神道と結びついた学校儀礼の物理的中心として機能した。御真影の保管・管理は校長以下教職員にとって重い責任であり、火災時に御真影を守ろうとして命を落とす事件が相次いだことは、奉安殿という施設の存在そのものが学校現場に大きな心理的重圧を課していたことを示している。\n\n第二次世界大戦後、GHQの占領下で進められた教育改革の一環として御真影の回収と教育勅語の失効が図られ、奉安殿もその役割を終えて多くが撤去・転用された。現在も一部の学校跡地や公園に奉安殿の遺構が残されており、戦前日本における天皇制と学校教育の結びつきを伝える歴史的遺産となっている。",
