    summary:
      "昭和20年(1945年)にGHQ内に設置された部局で、教育・宗教・文化・報道などを担当し、教育基本法の制定や教育委員会制度の導入など戦後日本の教育改革を指導した。",
    body: "民間情報教育局(Civil Information and Education Section、通称CIE)は、昭和20年(1945年)9月22日、連合国軍最高司令官総司令部(GHQ/SCAP)の下部組織として設置された部局である。当初はアメリカ太平洋陸軍総司令部の専門部局として発足し、同年10月2日にGHQ/SCAPへ移管された。日本および朝鮮に関する広報、教育、宗教その他の社会的事項について最高司令官に助言することを任務とした。\n\nCIEの活動範囲は極めて広く、初等・中等・高等教育から社会教育に至るまでの学校教育全般、教職員の適格審査(教員パージ)、新聞・雑誌・ラジオなどの報道メディア、映画・演劇などの文化芸術、神道・仏教・キリスト教などの宗教政策、世論調査、文化財保護にまで及んだ。教育分野では、来日した米国教育使節団への協力や教育刷新委員会との連携を通じて、教育基本法・学校教育法の制定、六・三・三・四制の導入、教育委員会制度の創設など、戦後教育改革の中核的な制度設計に深く関与した。\n\nCIEは昭和27年(1952年)4月のサンフランシスコ講和条約発効による占領終結まで活動を続けた。その指導のもとで進められた一連の改革は、戦前の中央集権的・国家主義的教育体制からの転換を促し、戦後日本の教育制度の骨格を形成する上で決定的な役割を果たしたと評価されている。",
