    title: "大学基準協会",
    reading: "だいがくきじゅんきょうかい",
    kana: "た",
    categories: ["history"],
    summary:
      "昭和22年(1947年)、アメリカのアクレディテーション団体を範として国公私立大学46校により設立された大学団体。その定めた「大学基準」が戦後の大学設置基準の原型となった。",
    body: "大学基準協会は、昭和22年(1947年)にアメリカの大学アクレディテーション団体をモデルとして、国立・公立・私立の大学46校により設立された大学の自主的な団体である。戦後の混乱期にあって高等教育制度が大きな変革期を迎える中、「会員の自主的努力と相互的援助によって、わが国における大学の質的向上を図る」ことを目的として発足した。\n\n同協会は設立と同時に「大学基準」を制定し、これが戦後の大学制度の質保証の基礎となった点が特に重要である。昭和22年(1947年)7月7日に開催された大学設置基準設定連合協議会が採択した「大学基準」は、翌日の大学基準協会創立総会でそのまま同協会の基準として採用され、さらに昭和23年(1948年)2月に文部省内に発足した大学設置委員会が、この大学基準に運用要綱を加える形で正式な大学設置基準として採用することを決定した。すなわち、現行の大学設置基準の直接の源流は、大学人自身が自主的に策定した大学基準協会の基準にある。\n\n大学基準協会はその後、大学の自己点検・評価や認証評価制度の担い手としての役割も担うようになり、平成16年(2004年)の認証評価制度導入以降は文部科学大臣の認証を受けた認証評価機関として大学評価事業を継続している。国家による一方的な統制ではなく大学人の自治的な質保証組織として出発した点に、戦後高等教育史における同協会の独自の意義がある。",
    relatedSlugs: ["daigaku-secchi-kijun", "daigaku-secchi-keitai", "senryo-ka-kyoiku-kaikaku"],
    isCanonical: true,
