    summary:
      "大正6年(1917年)、寺内正毅内閣のもとに設置された教育改革のための諮問機関。第一次世界大戦後の社会変動を背景に学校制度改革を審議し、大正・昭和初期の教育政策に影響を与えた。",
    body: "臨時教育会議は、大正6年(1917年)に公布された臨時教育会議官制に基づき、寺内正毅内閣のもとに内閣直属の諮問機関として設置された。内閣総理大臣の諮問に応じて教育に関する重要事項を調査審議することを任務とし、岡田良平文部大臣が第一次世界大戦後の社会変化に対応する学校制度改革を強力に推進するために主導して設けたものである。\n\n同会議は大正6年(1917年)10月1日に第1回総会を開き、大正8年(1919年)3月28日の第30回総会をもって審議を終了した。この間、教育界・産業界の有力者らが委員として参加し、高等教育の拡張、実業教育の振興、師範教育の改善など多岐にわたるテーマについて答申をまとめた。会議の議事録には、ロシア革命の成功や国内における労働争議・小作争議の激増、米騒動といった当時の社会不安に対する支配層の強い危機感が色濃く反映されていたことが指摘されている。\n\n臨時教育会議の答申は、大学令(1918年)や高等学校令の改正、専門学校の拡充など、大正期から昭和初期にかけての一連の教育制度改革の基礎となった。第一次世界大戦後の社会構造の変化に対応して高等教育を拡張しようとした点で、戦後の中央教育審議会や臨時教育審議会に連なる、政府主導の大規模な教育改革審議の先駆的事例として位置づけられている。",
