      "昭和42年(1967年)から東京都立高校入試に導入された制度。複数の高校をグループ化し合格者を機械的に振り分けることで学校間格差の是正を狙ったが、後に新たな格差や進学校の凋落を招き2004年頃までに姿を消した。",
    body: "学校群制度は、昭和42年(1967年)、東京都知事東龍太郎、教育長小尾乕雄のもとで東京都立高等学校の入学者選抜制度として導入された制度である。当時、越境入学や受験偏重教育、詰め込み教育の過熱が問題視されており、小尾教育長はその根本原因を「学校間格差」に求め、生徒がより有利とされる特定の高校への進学を目指して過度な受験競争に走っていると分析した。\n\n制度の仕組みは、地理的に近接する2ないし3校の都立高校をひとつの「学校群」としてグループ化し、受験生は学校ではなく学校群を単位として受験、合格者は群内の各校にほぼ均等に機械的な方法で振り分けられるというものであった。これは一種の総合選抜制度であり、特定の高校への一極集中を防ぎ、学校間の学力格差を平準化することを目指した。\n\n制度は一定程度、学校間の学力格差の平準化には効果を上げたが、一方で群と群の間に新たな序列が生まれる、日比谷高校をはじめとする従来の進学名門校の大学進学実績が急速に低下するなど、意図しない副作用も顕著となった。批判の高まりを受け、学校群制度は徐々に見直され、関連する総合選抜制度も含め2004年頃までにはほぼ姿を消した。学力格差是正を狙った入試制度改革が新たな課題を生んだ事例として、高校入試制度史上しばしば参照される。",
