    summary:
      "昭和22年(1947年)結成の都道府県教職員組合の全国連合体。勤務評定反対闘争など政府の文教政策への対抗運動を通じ、戦後日本の教育政策と教育行政の展開に大きな影響を与えた。",
    body: "日本教職員組合(略称・日教組)は、昭和22年(1947年)6月8日、奈良県橿原神宮外苑で結成大会が開かれた、都道府県単位の教職員組合を束ねる全国連合体である。第二次世界大戦後、各地で分立していた教職員の労働組合の間で、いわゆる二・一ゼネスト(1947年2月1日予定であったが直前に中止されたゼネスト)の準備を通じて協力の機運が高まり、組織を合同する形で発足した。\n\n発足当初は戦後民主化の担い手としての性格が強かったが、1950年代のいわゆる「逆コース」の潮流の中で、政府の文教政策と鋭く対立するようになった。昭和29年(1954年)の教育二法(教育公務員特例法の一部改正法・義務教育諸学校における教育の政治的中立の確保に関する臨時措置法)反対闘争、昭和31年(1956年)の教育委員任命制反対闘争、昭和32年から33年(1957~58年)にかけての勤務評定反対闘争など、一連の大規模な反対運動を展開した点は特筆される。勤務評定反対闘争は、教員の勤務成績を評定し人事管理に反映させようとする文部省・教育委員会の方針に対し、日教組が教育の自主性を損なうものとして強く抵抗した運動である。\n\n日教組はその後も教科書検定訴訟の支援や平和教育の推進などに取り組み、日本の戦後教育政策の展開において労使関係・教育行政・教育運動の各側面から重要な影響を及ぼし続けた組織として、教育史上大きな存在感を持っている。",
