    kana: "た",
    categories: ["history"],
    summary:
      "1960年代後半、東京大学をはじめ全国の大学で発生した学生運動・大学闘争。東大紛争は昭和44年(1969年)の安田講堂事件と入試中止に至り、大学制度・大学自治のあり方に大きな影響を残した。",
    body: "大学紛争(大学闘争)とは、1960年代後半、日本全国の大学で相次いで発生した学生による抗議運動・大学占拠運動の総称である。代表例である東京大学の紛争(東大紛争)は、昭和43年(1968年)1月、医学部の学生・研修医が研修医制度(インターン制度)に反対して無期限ストライキに入ったことに端を発する。同年6月15日には一部の医学部学生が大学本部のある安田講堂を占拠し、2日後には大学当局の要請で機動隊が本郷キャンパスに出動する事態となった。これを機に反発が拡大し、6月20日には10学部中8学部でストライキが行われ、約1万人規模の集会が開かれるなど、全学的な紛争へと発展した。\n\n大学当局の硬直的な対応が続く中、同年10月11日には全学部で無期限ストライキが行われ、11月1日には大河内一男総長が引責辞任した。昭和44年(1969年)1月10日、全学共闘会議系の学生代表団と大学側代理人との間で「確認書」が交わされ、医学部処分の撤回や自治活動の自由化など10項目が合意されたが、一部のグループはなお安田講堂などの占拠・封鎖を続けた。同年1月18日から19日にかけて機動隊が安田講堂の封鎖解除に踏み切り、多数の学生を検挙する「安田講堂事件」が発生した。この影響で、東京大学は昭和44年度の入学試験を中止し、その年の新入生を迎えないという異例の事態となった。\n\n同時期には日本大学をはじめ全国の多くの大学で同様の紛争が発生し、学生の政治参加や大学運営への発言権、大学の管理運営体制のあり方が広く問われた。政府はこれを受けて昭和44年(1969年)に大学の運営に関する臨時措置法を制定するなど収拾を図った。大学紛争は、大学自治や学生の位置づけをめぐる戦後最大級の教育・社会運動として、日本の高等教育史に大きな痕跡を残している。",
