      "律令制のもとで式部省に属し、中央官人の養成を担った官立の教育機関。明経道・紀伝道・明法道・算道などの学科が置かれた。",
    body: "大学寮は、大宝令(701年)に始まる律令制のもとで、式部省の管轄下に置かれた中央の官人養成機関です。都に置かれた官立の高等教育機関として、後の「大学」という語の源にもなりました。本科の教官は博士1人・助博士2人、学生は400人と説明されることが多く、入学資格には五位以上の貴族の子孫などが想定されていました。\n\n学科は、経書を学ぶ経学(のちの明経道)を本科とし、のちに歴史・文章を扱う紀伝道(文章道)、法律を学ぶ明法道、数学を学ぶ算道などが加わって整えられました。算道には算博士2名・算生30名が置かれたとされます。教育は儒教の経典の読解を軸とし、官人としての教養と実務能力の育成を目的としていました。\n\n平安時代には、有力氏族が一族の子弟のために大学の周辺に寄宿・学習の施設(大学別曹)を設けるようになり、大学寮そのものは次第に形骸化していきました。学問の担い手が特定の家系に固定化していく過程を示す例でもあり、後世の藩校や私塾の成立とも対比される、日本の公的教育機関の出発点として位置づけられます。",
