    body: "律令制の国学は、中央の大学寮に対応して、各国(地方行政区画)に置かれた官立の学校です。地方の官人や官吏候補を養成することが目的で、国博士・国医師といった教官が置かれ、おもに地方豪族である郡司クラスの子弟が学んだとされます。江戸時代に発達した、日本古来の思想や文献を研究する学問としての「国学」とは区別する必要があります。\n\n原則として国ごとに国学が置かれましたが、筑前・筑後・肥前・肥後・豊前・豊後の6か国には置かれず、大宰府に設けられた学校でその役割を担ったと説明されます。大宰府学校は、中央の大学寮と医学教育の機関を合わせたような性格を持つとされ、九州一円の郡司クラスの子弟が入学を許されたといわれます。\n\n国学の教育内容は、大学寮と同様に儒教の経書を中心とするものでした。中央集権的な官人養成の仕組みを地方に広げる試みでしたが、律令制の変質とともに衰え、平安時代を通じて実質を失っていったと考えられています。定員や運営の細部は時期によって異なり、史料による確認が必要な部分も多い分野です。",
