    body: "綜芸種智院は、真言宗の開祖である空海が、天長5年(828年)頃に京都に開いたとされる教育機関です。当時の大学寮や国学が貴族や郡司層の子弟に限られていたのに対し、身分にかかわらず学べる点が画期的とされ、日本で最初期の庶民にも開かれた私立学校として語られます。左京九条の藤原三守の邸宅に設けられたとする説明があります。\n\n名称の「綜芸種智」には、さまざまな学芸(芸)を総合し、あらゆる人の持つ可能性(種智)を育てるという意味が込められているとされます。教育内容は、仏教だけでなく儒教や道教なども含めて総合的に学ぶものでした。空海は設立の趣旨を述べた文章を残しており、教える者と学ぶ者の生活を支える仕組みにも配慮したと伝えられます。\n\n綜芸種智院は空海の没後(835年)ほどなく維持されなくなったとされ、長く続いた学校ではありません。それでも、官立の学校が貴族向けであった時代に、民間の立場から開かれた学びの場を構想したという点で、日本教育史上の先駆的な事例として評価されています。所在地や存続期間の細部には諸説があり、確定的でない点もあります。",
