    body: "明治期の日本では、1872年の学制以降、就学の奨励が進められましたが、義務教育の年限は当初から一定ではありませんでした。1900年(明治33年)の小学校令改正で、尋常小学校が4年制に統一され、授業料の原則不徴収も定められて、就学率は大きく上昇しました。文部科学省の資料によると、その後、1907年(明治40年)の小学校令改正により、義務教育は尋常小学校6年までに延長されています。\n\nこの結果、小学校は尋常小学校6年・高等小学校2年を基本とする体制となり、この仕組みは昭和前期まで続いたと説明されます。年限延長の背景には、就学率が高まり、国民の多くが尋常小学校に通うようになったこと、産業の発達や国力増強のために初等教育の水準を高める必要があったことなどが挙げられます。また、延長に伴って国による財政的な支えが課題となり、教員の増員や学校の整備が進められました。\n\nその後、戦時下の国民学校令(1941年)で義務教育を8年とする規定が設けられましたが、実施は見送られました。戦後の1947年に学校教育法が施行され、小学校6年・中学校3年の計9年が義務教育となります。義務教育年限の延長は、「どこまでを国民に共通の教育として保障するか」を示す指標であり、教育機会の拡大の歴史を理解する鍵になります。",
