      "1879年に明治天皇の名で示された教学の基本方針。元田永孚が起草し、仁義忠孝を重んじる徳育を重視して、教育政策の転換点となった。",
    body: "教学聖旨は、1879年(明治12年)8月に、明治天皇の名で示された教学の基本方針です。侍講の元田永孚が起草したとされ、「教学大旨」と「小学条目二件」から構成されます。洋風に走って知識・才芸の末に流れる風潮を戒め、仁義忠孝の精神を養う徳育を教育の基本にすえるべきだとする内容で、儒教主義の復活と評されます。背景には、前年に天皇が各地を巡幸して教育の実情を見たことがあるとされています。\n\n1872年の学制の趣旨(被仰出書)が個人の立身・治産・昌業を強調していたのに対し、教学聖旨は徳育を教育の中心に据え、国家が道徳に関与することを明確にした点で、大きな方針転換でした。草案を示された伊藤博文は、欧米の科学・技術の導入を急ぐ立場から、政府が道徳に介入することに反対したとされ、これに対して元田が祭政一致の立場から反論し、聖旨が示されたと伝えられます。\n\n1879年の教育令に対する批判が高まるなか、1880年12月に改正教育令が公布され、地方教育行政への国の統制が強まりました。修身を筆頭教科とする流れも進み、のちの教育勅語(1890年)へとつながっていきます。教学聖旨は、明治前期の教育政策が「開明的な文明開化」から「国家主義的な徳育重視」へ移る転換を示す文書として位置づけられます。",
