    body: "教科書疑獄事件は、1902年(明治35年)末に表面化した、検定教科書の採択をめぐる贈収賄事件です。日本では1886年に教科書検定制度が始まり、教科書会社が民間で教科書を発行し、各地で採択される仕組みが続いていました。この制度のもとで、採択を有利に進めるための贈収賄が各地で行われ、多数の関係者が摘発されたとされます。\n\n文部省の資料によると、この事件で当時の主要な小学校教科書が使用に適さないとされ、小学校教科書の検定による認可制度は事実上停止されました。もともと教科書の国定化を求める建議は衆議院・貴族院でもなされており、事件は国定化の流れを決定づける契機となりました。1903年(明治36年)に小学校教科書の国定制度が確定し、1904年(明治37年)から使用が始まります。\n\n国定制度のもとでは、修身・歴史・国語などで国家の統一的な価値観が強調されるようになりました。戦後は、1947年の学校教育法のもとで検定制度が復活しています。教科書疑獄事件は、教科書の質や公正さの問題が、教科書の内容を国が一元的に管理する制度へつながった歴史的事例として、教科書制度の歴史を考える際の出発点になります。",
