    body: "滝川事件は、1933年(昭和8年)に京都帝国大学法学部の滝川幸辰教授が文部省から休職処分を受けた事件で、京大事件とも呼ばれます。発端は、1932年の中央大学での講演や、滝川の著書『刑法読本』などが議会で「危険思想」として攻撃されたことでした。内務省は1933年4月に滝川の著書を発売禁止とし、文部省は同年5月25日に休職を決定しました。\n\n文部省の措置に対し、翌日、京大法学部教授会は学問研究の自由と大学の自治を侵すものとして抗議し、教授会として小西重直総長に辞表を提出しました。学生運動や他大学、報道機関を巻き込んだ政治問題に発展しましたが、教授会の抵抗は次第に切り崩され、分断されたといわれます。文部大臣は鳩山一郎でした。\n\nこの事件は、帝国大学の人事に政府が介入し、教授会の自治が実質的に無力化されていく過程を示すものとして、昭和戦前期の大学自治の歴史で重要な位置を占めます。戦後は、こうした経験への反省もあって、日本国憲法第23条で「学問の自由」が保障されたと説明されます。なお、発売禁止の日付などは資料により数日の差があります。",
