      "敗戦直後に文部省の寺中作雄らが構想し、1946年の文部次官通牒で設置が促された社会教育施設。1949年の社会教育法で法的根拠を得た。",
    body: "公民館は、戦後の日本で町村などの地域に設けられる社会教育施設で、その原型は、文部省公民教育課長だった寺中作雄らによる「寺中構想」にあります。寺中は著書『公民館建設』の中で、公民館を「われわれのための施設」と位置づけ、社会教育、社会娯楽、町村自治振興、産業振興、青年養成といった機能を持つ総合的な施設として構想したとされます。構想の成立時期は、1945年末ごろとする説明など、資料によって幅があります。\n\n1946年(昭和21年)7月5日、文部次官通牒「公民館の設置運営について」が地方長官に宛てて発せられ、公民館の設置が政策として打ち出されました。ただし、この通牒から1949年(昭和24年)6月10日の社会教育法の公布・施行までの約3年間、公民館には設置などに関する法的根拠がありませんでした。社会教育法により公民館が法律上位置づけられ、各地で条例の制定と設置が進んだとされます。\n\n公民館は、戦後民主主義を地域に根づかせる拠点として構想され、地域住民の学習・文化・交流の場として全国に広がりました。その後は生涯学習の流れの中で、地域づくりや学びの場としての役割が問い直され続けています。",
