    body: "教育委員会公選制は、戦後教育改革の一環として導入された、教育委員を住民が直接選挙で選ぶ制度です。米国教育使節団の報告や教育刷新委員会の提言を受け、1948年(昭和23年)に教育委員会法が制定されました。教育行政を一般行政から独立させ、住民の意思を反映させることがねらいでした。委員は住民の直接選挙で選ばれ、議会選出の委員も加わる仕組みでした。\n\n第1回の教育委員選挙は1948年10月5日に実施され、同年11月1日に都道府県などに教育委員会が置かれたとされます。市町村への設置は延期が重ねられ、1952年(昭和27年)に、すべての都道府県・市町村に教育委員会が置かれました。(選挙月については資料により食い違いがあります。)\n\nしかし、公選を通じて教育委員会に政治的対立が持ち込まれる弊害や、教職員組合の推薦を受けた人が多く選出されたことへの批判などが指摘されました。1956年(昭和31年)、教育委員会法に代わって「地方教育行政の組織及び運営に関する法律」が制定され、公選制は廃止されて、首長が議会の同意を得て委員を任命する方式に改められました。教育の民主化と政治的中立性のどちらを重んじるかという対立を示す、戦後教育行政史の重要な論点です。",
