    body: "勤務評定闘争(勤評闘争)は、1950年代後半に、教員に対する勤務評定の導入をめぐって日本教職員組合(日教組)が展開した反対運動です。発端は愛媛県で、県財政の赤字を理由に教員の昇給を対象者の7割に制限し、その決定に勤務評定を使う方針が、1956年11月に示されたことでした。愛媛での闘争は1956年11月から1957年6月の第一次、1957年10月から12月の第二次に分けて整理されます。\n\n愛媛の問題が深刻化するなかで、1957年12月に都道府県教育長協議会が「教職員の勤務評定試案」を発表し、各県は1958年4月の実施を目指しました。日教組は特定の地域を拠点として運動を重点的に展開する戦術をとり、和歌山・群馬・高知などで紛争が激化したとされます。1958年9月15日には全国で統一行動が行われました。教員の勤務評定は、1958年(昭和33年)以降、実施されるようになったと説明されています。\n\n勤評闘争は、教員を管理・評価する教育行政の側と、教員の自主性や労働条件を守ろうとする組合の側の対立が先鋭化した事件でした。同時期の地教行法制定(1956年)や学力テストなどとあわせて、1950年代から60年代の教育をめぐる政治的な対立を理解する重要な背景です。",
