    body: "旭川学力テスト事件は、1961年(昭和36年)度に文部省が実施した全国中学校一斉学力調査をめぐって、北海道旭川市で起きた事件です。文部省は、地方教育行政の組織及び運営に関する法律54条2項を根拠に、各教育委員会に調査と結果の報告を求めました。これに反対する運動のなかで調査の実施を阻止する行為があり、関係者が起訴され、調査の適法性や教育内容を決める権限が法廷で争われました。\n\n1976年(昭和51年)5月21日、最高裁判所大法廷は判決を示しました。判決は、小・中・高校の教師にも一定の範囲で教授の自由が認められるとしつつ、教育の機会均等や全国的な水準確保の要請などから、完全な教授の自由を認めることはできないとしました。1960年代以降続いていた、国が教育内容を決定する権限を持つとする「国家の教育権」論と、親・教師を中心とする国民が持つとする「国民の教育権」論の対立に、一つの整理を示した判決と評価されています。\n\nこの判決は、教育基本法10条にいう「不当な支配」の解釈についても判断を示しました。教育行政にも不当な支配が及び得るとされたため、現在でも、教育行政と教育の自主性の関係を論じる際にしばしば参照されます。なお、判決の詳しい判示内容は、判例集などの原文で確認することをお勧めします。",
