    body: "新制大学は、戦後の教育改革で、学校教育法のもとに新たに設けられた四年制大学です。戦前は帝国大学、専門学校、高等学校、師範学校などが並立して複線型の高等教育を形づくっていましたが、戦後はこれを大学に一本化し、六・三・三・四制の最上段に位置づけました。国立大学は、1949年(昭和24年)の国立学校設置法(同年5月31日)に基づいて発足し、1949年度に第1学年から始まって、学年進行により1952年(昭和27年)に四年制の大学として完成したと説明されます。旧制の学校は、在学者が卒業するまで新制大学に包括される形で存続しました。\n\n国立大学では「一府県一大学」の実現が方針とされ、各都道府県に教員養成を担う学部を置くことなどが目指されました。たとえば、複数の師範学校や青年師範学校が統合されて学芸大学・学芸学部・教育学部などに再編され、旧制高等学校が既存の大学に包括された例があります。\n\n新制大学の発足により、高等教育の機会は大きく広がりました。一方で、旧制の専門学校や師範学校の伝統をどう引き継ぐかや、教養教育と専門教育の関係など、課題も残されました。のちの大学設置基準の整備や、短期大学の恒久化などにもつながる、戦後高等教育の出発点です。",
