    summary:
      "12〜13世紀のヨーロッパで、教師や学生の自治的なギルド(ウニヴェルシタス)として成立した大学。ボローニャ型とパリ型が代表。",
    body: "ヨーロッパの大学は、12〜13世紀にかけて、教師や学生が学ぶ場所を求めて集まり、自治的な団体を作ったことから生まれました。「ウニヴェルシタス」(universitas)という語は、もとは教師や学生のギルド(組合)を指すものでした。14世紀後半には、世俗権力や教会権力に認められた、自律的に運営される教授と学徒の共同体を意味する語として定着していったとされます。\n\n代表的な例が、イタリアのボローニャ大学とフランスのパリ大学です。ボローニャは法学の学校が集まって学生の自治団体が生まれた型で、学生が主体となったと対比されます。1158年に神聖ローマ皇帝フリードリヒ1世が法学生に与えた特許状が、その存在を公認する契機になったとされます。ボローニャ大学には明確な創立年がなく、よく言われる1088年は八百年祭の際に定められた年です。パリ大学は、司教座聖堂付属の学校で神学などを学ぶ人々が集まり、まず教師たちが団体を作り、のちに教師と学生の団体となったとされ、教師が主体の型とされます。\n\n学生や教師はしばしば他の都市へ移動して新しい大学を生み、オックスフォードやケンブリッジなどが成立しました。教育は、自由学芸を基礎として、神学・法学・医学といった上級学部で学ぶ構成が一般的で、学位の授与によって専門職への道が開かれました。大学の自治・学位・学部の構成は、近代以降の大学制度の源流とされます。",
