    body: "1870年初等教育法は、通称フォースター法とも呼ばれる、イギリスの初等教育の歴史における画期的な法律です。19世紀のイギリスでは、教会などが運営する民間の学校が初等教育を担っていましたが、数が足りない地域がありました。この法律は、既存の任意設立の学校を存続させたうえで、不足する地域には学務委員会(スクール・ボード)を設置して学校を建てる仕組みを定めました。委員会は選挙で選ばれ、財源は地方税でした。\n\nこの法律は、義務教育を導入したわけではありませんでした。授業料も廃止されず、無償でも義務でもない点は、近年の研究でも指摘されています。義務化の権限は、各地の学務委員会が就学を強制するかどうかを選ぶ形で、地域の判断に委ねられました。対象年齢は資料によって5〜12歳、5〜13歳などの記述があり、法の枠組みとしての年齢と、委員会ごとの規定とを区別して読む必要があります。\n\n全国的な義務化は、1880年前後の法律(ムンデラの名で知られる)で進んだとされますが、1880年とする資料と1881年とする資料があり、年は確定しにくい点です。1870年法は、国が初等教育の提供に責任を持つという原則を確立した出発点として、公教育の成立史で重視されます。",
