    body: "幕末の1856年（安政3年）、江戸幕府が黒船来航後の国際情勢に対応するため、従来の天文方蕃書和解御用を改組・拡充して設立した洋学（蘭学・洋学）の研究・教育機関である。当初は洋学所と称し、のちに蕃書調所と改称された。\n\nオランダ語をはじめ、英語・フランス語・ドイツ語・ロシア語などの西洋語学の教授、地理・歴史・数学・物理・化学などの翻訳および研究、さらには洋書の出版・管理を担った。古賀謹一郎を筆頭に、箕作阮甫、杉田玄端ら当代一流の蘭学者・洋学者が教授として参画した。\n\nその後、洋書調所、開成所と改称・拡充を重ね、明治維新後に大学南校などを経て東京大学へと発展・統合された。近代日本における高等教育と西洋科学受容の草分け的機関として、教育史上極めて重要な位置を占める。",
