    body: "1878年（明治11年）、文部省が近代学校教育における体操（学校体育）の指導者を養成し、体操の研究および教材開発を行うために東京に設置した官立機関である。明治初期の学校において生徒の体格向上と健康維持が急務とされたことを背景に設立された。\n\nアメリカから体育指導者ジョージ・リーランドが招かれ、主幹の近藤鎮三らとともにアメリカの軽体操や器械体操、解剖生理学などを導入した。リーランドの指導の下、理論と実技を兼ね備えた体操科教員が体系的に育成された。\n\n同所で制定された普通体操法などの教材は全国の師範学校や小学校に普及し、日本の近代学校体育の出発点となった。1886年の諸学校令公布に伴い東京師範学校に統合され、後の高等師範学校体操専修科へと継承された。",
