    body: "第二次世界大戦末期の1944年、イギリスの挙国一致内閣の下で教育委員会総裁R・A・バトラーの主導により成立した教育法であり、通称「バトラー法」と呼ばれる。戦後イギリスの教育制度の骨格を築いた歴史的法律である。\n\n同法は、それまで階級によって分断されていた初等教育と中等教育を整理し、「すべての青年に中等教育を」という理念の下、公立中等教育の授業料を無償化し、義務教育終了年齢を14歳から15歳へと引き上げた。また、中央行政として教育省を新設し、国家の教育責任を明確化した。\n\n中等教育は11プラス試験の結果に基づき、大学進学を目指すグラマースクール、実務・技術教育を担うテクニカルスクール、普通教育を行うモダンスクールの3種に分岐する制度が採用された。この分岐制は後に能力主義的選抜として批判を浴び、総合制学校への改革運動を引き起こす発端ともなった。",
