    body: "律令制における大学寮は、大宝律令および養老律令の制定に伴って式部省のもとに設置された古代日本の官立高等教育機関である。中国唐代の国子監制度を範として整備され、貴族や有力官人の子弟を将来の律令国家を担う官吏として組織的に養成することを目的とした。\n\n教育課程は儒教経典を学ぶ明経道を中核とし、律令法を学ぶ明法道、歴史や文学を修める紀伝道（文章道）、計算技術を教授する算道などの専門学科が置かれた。学生は直講や助教の指導のもとで経書の講読や試験に励み、国家による厳格な官吏登用試験を経て官僚へと登用された。\n\n大学寮の成立は、氏姓制に基づく世襲支配から法と文書に基づく官僚統治への転換を教育面から支える画期となった。平安期には有力氏族が独自の大学別曹を設けるなど変質したが、日本における国家的な官吏養成制度の原点として教育史上に重要な足跡を残した。",
