    body: "五山文学とは、鎌倉末期から室町時代にかけて、京都五山・鎌倉五山を中心とする臨済宗の禅僧らによって担われた学問・文学活動の総称である。中国の宋・元・明の文化を直接受容した禅僧たちが、中世日本の学問と教養の最高峰を形成した。\n\n禅僧たちは漢詩文の創作にとどまらず、宋代に成立した朱子学などの新儒学を深く研究し、注釈書の講義や漢籍の出版（五山版）を精力的に行った。足利将軍家や守護大名の政治顧問・外交顧問を務めるとともに、武士や文人層に対する高度な教育教授を担った。\n\n官立大学が衰退した中世において、五山禅林は知的遺産を保存し更新する事実上の高等教育機関として機能した。ここで蓄積された儒学の学統は、江戸時代の儒教隆盛や近世学校教育の発展へと直結する決定的な橋渡しとなった。",
