    body: "庭訓往来は、南北朝時代から室町初期にかけて成立したとされる手紙形式の初等教科書である。「庭訓」とは家庭における教えを意味し、武家社会の実務に即した文字学習と道徳教育を目的として編纂された。\n\n内容は1月から12月までの月ごとの往復書簡12往復（計24通）で構成され、季節の挨拶から仏事、武具、建築、衣食住、医薬、商業に至るまで当時の生活全般の語彙が網羅されている。学習者は手本を書き写す「手習い」を通じて語彙と筆記法を同時に習得した。\n\n江戸時代に入ると寺子屋の標準的教科書として全国で採用され、注釈本や挿絵入りの版本が大量に出版された。数世紀にわたり日本人の基礎的な読み書き教育と実務教養を規定した、近世初等教育史を代表する記念碑的教材である。",
