    body: "会輔堂は、江戸時代前期の儒学者・本草学者である貝原益軒が福岡に開いた学問の拠点である。益軒は空理空論を排し、人々の日常生活に真に役立つ知識と徳行を重視する「実学」の立場から教育と研究を推進した。\n\n益軒は会輔堂において門弟の指導にあたるとともに、地域住民に対する教化活動や庶民向けの著述に力を注いだ。平易な和文を用いて教育論を体系化した『和俗童子訓』や健康管理の規範を示した『養生訓』を著し、家庭教育や幼児期の心身の発達段階に応じた指導法を提唱した。\n\n会輔堂における益軒の実践は、近世日本における家庭教育論および庶民道徳教育の理論的基礎を築いた。学問を特権階級から解き放ち、生活改善と社会福祉に結びつける近世実学教育の典型として、教育思想史において高く評価されている。",
