    body: "古義堂は、寛文2年（1662年）に町人出身の儒学者・伊藤仁斎が京都堀川の自邸に開いた私塾であり、堀川塾とも呼ばれる。当時主流であった官学の宋朝朱子学を批判し、古代の原典に直接立ち返る「古義学」を教授する場として創設された。\n\n塾の教育手法は、一方的な講義ではなく、塾生同士による活発な討論（会読）を重視した点が画期的であった。身分や貧富にかかわらず全国から志ある門弟を広く受け入れ、日々の読書と道徳的対話を通じて自己の修養と批判的思考力を鍛え上げた。\n\n古義堂は仁斎の子である伊藤東涯らによって継承され、約200年間にわたり数千人の人材を輩出した。民間の自律的な学問共同体としての運営手法は、後の近世私塾の発展や会読を中心とする近代的主体的学習の源流として極めて高い歴史的価値を持つ。",
