    body: "閑谷学校は、寛文10年（1670年）に岡山藩主池田光政の命により、備前国和気郡閑谷の地に開設された郷学である。領内の安定と道徳的教化を図るため、武士階級のみならず領民や庶民の子弟に門戸を開いた画期的な公設教育機関であった。\n\n学校には孔子を祀る聖廟や講堂、学習者のための寮舎が完備され、津田永忠らの指導のもとで堅牢な石塀と瓦葺きの壮麗な校舎群が整備された。教育内容としては儒学の素読や礼節の指導が基本とされ、身分の別を問わず学問に励む環境が提供された。\n\n藩営でありながら領民教育を恒久的に保障するために独自の基本財産（学田）が設定され、藩主交代や財政難でも存続する先駆的な学校経営が実現した。世界最古級の庶民公立学校として、日本の近代学校制度にも先駆ける偉大な教育的遺産である。",
