    body: "鳴滝塾は、文政7年（1824年）にオランダ商館医として来日したフィリップ・フランツ・フォン・シーボルトが長崎郊外の鳴滝に開設した診療所兼学塾である。西洋の先進的な医学や科学技術を志す日本の青年医師・蘭学者を育成するために設立された。\n\nシーボルトは出島から通って塾生を直接指導し、外科手術の実演や臨床講義、植物学や動物学の野外実習を行った。塾生には高野長英や伊藤玄朴らが名を連ね、彼らはオランダ語での論文執筆や日本の動植物・風俗に関する共同調査を担当した。\n\n鳴滝塾は、書物中心の文献蘭学から実験と観察を重んじる実践的近代科学教育への転換を決定づけた。シーボルト事件による閉鎖後も、ここで学んだ俊英たちは幕末・維新期の近代医学導入や種痘の普及、衛生制度の構築において指導的な役割を果たした。",
