    body: "芝蘭堂は、天明6年（1786年）に蘭学者・大槻玄沢が江戸京橋に開いた蘭学私塾である。杉田玄白や前野良沢に学んだ玄沢が、後進の育成とオランダ語・西洋科学の普及を目的として創設し、寛政から文化期にかけて全国の蘭学研究の中心となった。\n\n玄沢は難解とされたオランダ語の学習法を体系化し、日本初の本格的入門書『蘭学階梯』を著して塾生を体系的に指導した。また寛政6年（1794年）には太陽暦の元日を祝う「新元会（オランダ正月）」を主催し、蘭学者や知識人の学術交流の場を提供した。\n\n芝蘭堂からは稲村三伯や宇田川玄随など優れた学者が輩出し、日本初の蘭和辞書『ハルマ和解』の編纂や西洋科学書の翻訳へと結実した。江戸における組織的な洋学教育の確立者として、近代日本の科学技術受容の土台を築いた教育的意義を持つ。",
