    body: "新井白石の学問形成と幕政教育論は、木下順庵の門下で朱子学を修めた白石が、第6代将軍徳川家宣および第7代家継の侍講として展開した政治的・道徳的な指導実践である。武断政治から文治政治への転換を教育と言語政策の面から完成させようとした。\n\n白石は将軍に対する進講を通じて儒教の王道政治を説き、儀礼や法度の整備を進めるとともに、実証的歴史書『読史余論』や地誌『古史通』を著した。またイタリア人宣教師シドッチの尋問記録から『西洋紀聞』をまとめ、地理学や国際認識の重要性を幕府中枢に示した。\n\n白石の教育的指導は、儒学を単なる個人の修養にとどめず、国家統治の科学や歴史の批判的検討へと昇華させた。為政者の教養形成が政策決定に直結することを示した先駆例であり、江戸中期以降の幕臣教育や藩校教育の規範的モデルとなった。",
