    body: "明倫館は、享保4年（1719年）に長州藩（萩藩）の第5代藩主毛利吉元が家臣教育のために創設した藩校である。藩士の道徳的退廃を防ぎ、文武両道に優れた優秀な人材を組織的に養成することを目的として開校された。\n\n嘉永年間には藩政改革に伴い萩の江向へと大幅に移転・拡張され、広大な敷地に文場、武場、兵学寮、医学館などが整備された。儒学や国学のほか、幕末の軍事情勢に対応して洋式兵学や砲術、造船術などの実学教育を積極的にカリキュラムへ導入した。\n\n明倫館は松下村塾などの民間私塾と並び立ち、長州藩が幕末維新の激動を主導する政治家や軍人を輩出する中核的な教育母体となった。近世藩校が軍事的・技術的近代化の要求に適応して変貌を遂げた代表的な成功事例として位置づけられる。",
