    body: "日新館は、享和3年（1803年）に会津藩家老の田中玄宰の進言により、藩主松平容敬（容大の代）のもとで創設された会津藩の最高学府である。藩政改革の根幹として教育重視を掲げ、会津若松城下西名子屋に壮大な敷地と施設を構えて誕生した。\n\n10歳以上の藩士子弟全員の入学が義務付けられ、儒学の素読や歴史、習字のほか、水練場を含む武芸教育、天文学や医学などの専門教育が体系的に施された。また、城下の集落ごとに行われた少年組織（什）の教育と連動し、規律ある集団生活が指導された。\n\n日新館の徹底した人格教育と文武の修練は、幕末の激動期において高い結束力と誇りを示した会津藩士の精神的中核となった。近世藩校教育の完成形態の一つとされ、近代日本の規律重視の教育方針にも少なからぬ影響を及ぼした。",
