    body: "錬成科は、1941年に公布された国民学校令の下で、国家総力戦に即応する少国民を育成するために構想された戦時総合教科の枠組みである。日中戦争から太平洋戦争へと拡大する歴史的背景の中、従来の分科的な知識教授を否定し、国家主義的な人格形成と皇国民の錬成を一体的に進めることが求められた。\n\nこの教科編成では、修身を中心に据えつつ、国語、国史、地理などの人文系科目を緊密に連関させた総合的な教授形態がとられた。机上の学力習得にとどまらず、皇国の精神や国土の認識、国策への奉仕精神を身体的に鍛練し内面化させる指導が行われ、教科活動全体が戦争遂行への動員態勢に直結した。\n\n戦時下の総合教科編成は、教科の壁を越えた統合的学習という形態をとりながらも、国家主義的教化に奉仕した歴史的限界を持つ。戦後の教育改革ではその軍国主義的性格が徹底して批判され、新教育における社会科の新設や民主主義教育の導入へと向かう契機となった。",
