    body: "戦後社会科の新設は、1947年の学制改革に伴い実施された教育課程の最重要改革の一つである。戦前の皇国思想を支えた修身、国史、地理を廃止し、占領軍の指導と米国の教育理論を取り入れながら、平和で民主的な共同社会を建設する主権者を育成する目的で創設された。\n\n従来の暗記を中心とする分科教育を改め、現実の社会生活における身近な問題を解決する単元学習が採用された。児童生徒が地域の調査や見学、討論、発表などの主体的な活動を通じて社会の構造や人間関係を批判的かつ協働的に理解する教授形態がとられた。\n\n社会科は、新教育の理念を体現する看板教科として全国の教育現場で熱心に実践され、民主主義的な公民教育の土台を築いた。その後、基礎学力論争や冷戦期における指導要領改訂を通じて知識の系統化が進められたが、現代の探究学習や主権者教育の原点として息づいている。",
