    body: "産業教育振興法は、1951年6月に制定された産業・職業教育振興のための基本法である。戦後の日本経済の復興と自立を支える産業人の育成が急務となる中、普通教育に偏りがちであった戦後新学制のもとで立ち遅れていた実業・職業教育を強力に支援する目的で成立した。\n\n本法に基づき、農業、工業、商業、水産などの産業教育を担当する公立高等学校や中学校に対し、実験実習設備や機械・器具の整備費用について国庫が一定割合を補助する制度が確立された。また、産業教育審議会の設置や、実習を担当する教員の特別手当支給など、物的・人的両面からの支援体制が整えられた。\n\nこの国庫補助制度は、全国の職業高校における最新設備の整備を後押しし、1960年代の高度経済成長を技術面から支える中堅人材の育成に決定的な貢献を果たした。産業構造の変化に対応した近代職業教育政策の先駆的法制として高く評価される。",
