    body: "理科教育振興法は、1953年8月に制定された科学教育支援のための法律である。第二次世界大戦後の荒廃から立ち直り、国際社会における科学技術立国を目指す中で、学校教育における理科教育の刷新と実験・観察環境の近代化を国家戦略として推進するために成立した。\n\n本法は、小学校、中学校、高等学校等の理科教育に必要とされる設備や器具の標準基準（理科教育設備基準）を法令で明確に定めた。公立学校がこれらの実験器具や標本、観察用具を整備する際、経費の2分の1を国庫が負担する補助金制度が創設され、全国の学校で理科室の整備が急速に進んだ。\n\n本法の施行は、黒板と教科書に依存していた日本の理科授業を、児童生徒自らが実験や実習を体験する探究的教育へと脱皮させる決定打となった。戦後日本の卓越した科学技術や自然科学研究の発展を初等中等教育の底辺から支えた教育史的意義は極めて大きい。",
