    body: "学校給食法は、1954年6月に公布・施行された学校給食の基本法である。戦後の極度な食糧難の中で始まった救援物資による給食事業を脱し、学校給食を義務教育における正式な教育活動として制度的に位置づけるために制定された。\n\n本法は、児童生徒の健全な心身の発達と食生活の改善を目的とし、パンなどの主食、ミルク、おかず（副食）からなる「完全給食」の普及を強力に後押しした。施設設備や人件費は学校設置者が負担し、食材料費は保護者が負担するという費用負担原則を確立するとともに、困窮世帯への就学援助措置を設けた。\n\n本法の成立により、学校給食は単なる栄養補給から健康管理や望ましい人間関係を育む教育的営みへと発展した。その後の中学校給食の拡大や食育基本法と連動した食育の推進など、日本の学校給食体制を世界的に高く評価される水準へと導く決定的な基礎となった。",
