    body: "国立大学法人法は、2003年7月に成立し、翌2004年4月から施行された大学改革の根幹法である。文部科学省の内部組織であった国立大学を国から切り離して独立した法人格を付与し、自己責任に基づく自律的運営と競争力の強化を促す行政改革の一環として断行された。\n\n本法により、従来の教授会を中心とする合議制から、学長を最高責任者とする迅速な意思決定構造（役員会、教育研究評議会、学外有識者を含む経営協議会）へと移行した。国から提示される中期目標に基づき各大学が中期計画を策定し、第三者機関による実績評価を通じて運営費交付金が配分される仕組みが整備された。\n\n本改革は、明治以来の国立大学の在り方を根本から再編し、産学連携や個性化、経営意識の導入を加速させた。しかし、運営費交付金の削減に伴う基礎研究環境の悪化や大学の自治の変容をめぐる議論など、現代高等教育の最前線に大きな課題を提起し続けている。",
